const $ = selector => document.querySelector(selector);
const token = new URLSearchParams(location.search).get("session") || new URLSearchParams(location.search).get("token");
const headers = extra => token ? {...extra, "X-Workbench-Token": token} : extra;
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let validatedDraft = null;
let generatedDraftBase = null;
let guidedStep = 1;
let runtimeCompatible = false;
const EXPECTED_WORKBENCH_API_CONTRACT = "p8.1-runtime-identity-v1";
const REQUIRED_STUDY_CAPABILITIES = [
  "study.constraint.structured_evaluation_plan",
  "study.protocol.execution_contract",
];

function renderRuntimeIdentity(identity, error=null) {
  const host = $("#runtime-identity");
  const capabilities = new Set(identity?.study_contract_capabilities || []);
  const missing = REQUIRED_STUDY_CAPABILITIES.filter(item => !capabilities.has(item));
  runtimeCompatible = !error && identity?.identity_version === 1 && identity?.api_contract_version === EXPECTED_WORKBENCH_API_CONTRACT && missing.length === 0;
  $("#guided-study").disabled = !runtimeCompatible;
  $("#new-study").disabled = !runtimeCompatible;
  if (!runtimeCompatible) {
    const reason = error ? error.message : identity?.api_contract_version !== EXPECTED_WORKBENCH_API_CONTRACT ? `backend contract ${identity?.api_contract_version || "unavailable"}; browser expects ${EXPECTED_WORKBENCH_API_CONTRACT}` : `missing backend capabilities: ${missing.join(", ") || "identity contract"}`;
    host.className = "runtime-identity incompatible";
    host.innerHTML = `<strong>WORKBENCH VERSION MISMATCH</strong><p>${esc(reason)}. Stop this server and restart the Workbench from the intended current workspace. Study creation and registration are disabled.</p>`;
    return false;
  }
  host.className = "runtime-identity compatible";
  host.innerHTML = `<details><summary>Backend verified — ${esc(identity.package_version)} · schema v${esc(identity.research_schema_version)} · PID ${esc(identity.process_id)}</summary><dl><dt>API contract</dt><dd>${esc(identity.api_contract_version)}</dd><dt>Launch mode</dt><dd>${esc(identity.launch_mode)}</dd><dt>Python</dt><dd class="locked-value">${esc(identity.python_executable)}</dd><dt>Backend source</dt><dd class="locked-value">${esc(identity.backend_module)}</dd><dt>Static source</dt><dd class="locked-value">${esc(identity.static_root)}</dd><dt>Study contract SHA-256</dt><dd class="locked-value">${esc(identity.study_contract_sha256)}</dd><dt>Studies assets SHA-256</dt><dd class="locked-value">${esc(identity.studies_assets_sha256)}</dd></dl></details>`;
  return true;
}

async function verifyRuntimeIdentity() {
  try {
    return renderRuntimeIdentity(await jsonFetch("/api/runtime-identity"));
  } catch (error) {
    return renderRuntimeIdentity(null, error);
  }
}

function requireCompatibleRuntime() {
  if (runtimeCompatible) return true;
  $("#runtime-identity").scrollIntoView();
  return false;
}

const GROUPS = [
  ["conditions", "Conditions", ["condition_key","label","role","exact_factor_definition"]],
  ["blocks", "Blocks", ["block_key","label","block_definition"]],
  ["constraint_definitions", "Constraint definitions", ["constraint_key","constraint_type","constraint_text","is_hard_constraint","evaluation_rule","permitted_result_provenance","unknown_handling"]],
  ["outcome_definitions", "Outcome definitions", ["outcome_key","role","unit_of_analysis","outcome_definition","computation_rule","missing_data_rule","refusal_handling","operational_failure_handling"]],
  ["analysis_definitions", "Analysis definitions", ["analysis_key","outcome_key","analysis_population","comparison_definition","aggregation_rule","exclusion_rule","reporting_rule"]],
  ["planned_runs", "Planned runs", ["run_key","condition_key","block_key","replicate_number","randomized_ordinal","planned_prompt_text","planned_source_system","replacement_for_run_key","applicable_constraint_keys"]],
];

function fieldControl(field, value="") {
  if (field === "role") return `<select data-field="${field}"><option value="">Select…</option><option>CONTROL</option><option>TREATMENT</option><option>PRIMARY</option><option>SECONDARY</option><option>EXPLORATORY</option></select>`;
  if (field === "permitted_result_provenance") return `<select data-field="${field}"><option value="">Select…</option><option>DIRECT_OBSERVATION</option><option>HUMAN_ASSESSMENT</option><option>DERIVED_QUERY_RESULT</option><option>MIGRATION_DERIVATION</option></select>`;
  if (field === "is_hard_constraint") return `<select data-field="${field}"><option value="true">Hard</option><option value="false">Soft</option></select>`;
  if (field === "planned_prompt_text") return `<textarea class="short" data-field="${field}" placeholder="${esc(field)}">${esc(value)}</textarea>`;
  const numeric = ["replicate_number","randomized_ordinal"].includes(field);
  return `<input data-field="${field}" ${numeric ? 'type="number" min="1"' : ''} value="${esc(value)}" placeholder="${esc(field)}${field === 'applicable_constraint_keys' ? ' (comma-separated)' : ''}">`;
}
function addRow(group, values={}) {
  const spec = GROUPS.find(item => item[0] === group); const host = $(`#${group}-rows`);
  const row = document.createElement("article"); row.className = "study-row";
  row.innerHTML = `<div class="study-row-grid">${spec[2].map(field => `<label>${esc(field)}${fieldControl(field, values[field])}</label>`).join("")}</div><button class="remove ghost" type="button">Remove</button>`;
  spec[2].forEach(field => { const input=row.querySelector(`[data-field="${field}"]`); if (values[field] !== undefined) input.value = values[field] === null ? "" : field === "applicable_constraint_keys" && Array.isArray(values[field]) ? values[field].join(", ") : String(values[field]); input.addEventListener("input", invalidate); input.addEventListener("change", invalidate); });
  row.querySelector(".remove").onclick=()=>{row.remove();invalidate();}; host.append(row); invalidate();
}
function buildGroups() { $("#draft-groups").innerHTML = GROUPS.map(([key,title]) => `<section class="declaration-block"><div class="subhead"><h3>${title}</h3><button type="button" class="secondary" data-add="${key}">Add</button></div><div id="${key}-rows" class="card-list"></div></section>`).join(""); document.querySelectorAll("[data-add]").forEach(b=>b.onclick=()=>addRow(b.dataset.add)); }
function invalidate(){validatedDraft=null;$("#review-study").disabled=true;$("#draft-status").textContent="Draft changed. Validate again.";}
function val(id){return $(id).value;}
function validationIssueText(issue){return window.GuidedStudyBuilder.formatValidationIssue(issue);}
function collectGroup(key){return [...$(`#${key}-rows`).children].map(row=>{const out={};row.querySelectorAll("[data-field]").forEach(input=>{let value=input.value;if(["replicate_number","randomized_ordinal"].includes(input.dataset.field)) value=Number(value);if(input.dataset.field==="is_hard_constraint") value=value==="true";if(input.dataset.field==="applicable_constraint_keys") value=value.split(",").map(x=>x.trim()).filter(Boolean);if(input.dataset.field==="replacement_for_run_key"&&!value)value=null;out[input.dataset.field]=value;});return out;});}
function collectDraft(){const protocol={version_number:Number(val("#version-number")),amendment_reason:null,objective:val("#objective"),primary_hypothesis:val("#primary-hypothesis"),null_hypothesis:val("#null-hypothesis"),design_summary:val("#design-summary"),planned_sample_size:Number(val("#sample-size")),randomization_method:val("#randomization-method"),randomization_seed:val("#randomization-seed"),operational_failure_policy:val("#operational-policy"),operational_failure_consumes_run:$("#operational-consumes").checked,refusal_policy:val("#refusal-policy"),missing_result_policy:val("#missing-policy")};GROUPS.forEach(([key])=>protocol[key]=collectGroup(key));if(generatedDraftBase){const prior=new Map((generatedDraftBase.protocol.constraint_definitions||[]).map(item=>[item.constraint_key,item]));protocol.constraint_definitions=protocol.constraint_definitions.map(item=>({...prior.get(item.constraint_key),...item}));protocol.execution_contract=generatedDraftBase.protocol.execution_contract;}return {study_key:val("#study-key"),title:val("#study-title"),protocol};}
async function jsonFetch(url,options={}){const response=await fetch(url,{...options,headers:headers({"Content-Type":"application/json",...(options.headers||{})})});const contentType=response.headers.get("Content-Type")||"";let body=null;if(contentType.includes("application/json")){body=await response.json();}else{await response.text();}if(!response.ok)throw new Error(body?.error||`HTTP ${response.status}`);if(body===null)throw new Error("Server returned a non-JSON response.");return body;}
async function loadStudies(){const body=await jsonFetch("/api/studies");const host=$("#study-list");host.innerHTML=body.studies.length?body.studies.map(s=>{const current=s.protocol_versions.at(-1);return `<article class="entry-card"><strong>${esc(s.study_key)} — ${esc(s.title)}</strong><p>Version ${current?.version_number||"—"} · REGISTERED · ${current?.registered_at||"—"}</p><p>Runs ${s.realized_run_count}/${s.planned_run_count} realized · ${s.operational_attempt_count} operational attempts · ${s.remaining_executable_run_count} executable</p><button data-open-study="${s.id}" type="button">Open</button></article>`;}).join(""):'<p class="empty">No registered studies.</p>';document.querySelectorAll("[data-open-study]").forEach(b=>b.onclick=()=>openStudy(Number(b.dataset.openStudy)));}
function newDraft(){localStorage.removeItem("pne-study-draft");generatedDraftBase=null;$("#guided-panel").hidden=true;$("#draft-panel").hidden=false;$("#review-panel").hidden=true;$("#registered-panel").hidden=true;$("#run-panel").hidden=true;$("#evaluation-panel").hidden=true;$("#exploration-panel").hidden=true;$("#closeout-panel").hidden=true;document.querySelectorAll("#draft-panel input,#draft-panel textarea").forEach(x=>{if(!["version-number"].includes(x.id))x.value="";});GROUPS.forEach(([key])=>$(`#${key}-rows`).innerHTML="");$("#advanced-technical-json").textContent="No complete generated protocol is attached to this manual draft.";invalidate();$("#draft-panel").scrollIntoView();}
function populateDraft(draft,message="Generated guided draft loaded. Validate before registration review."){generatedDraftBase=JSON.parse(JSON.stringify(draft));$("#draft-panel").hidden=false;$("#study-key").value=draft.study_key||"";$("#study-title").value=draft.title||"";const p=draft.protocol||{};const fields={"#version-number":p.version_number,"#sample-size":p.planned_sample_size,"#objective":p.objective,"#primary-hypothesis":p.primary_hypothesis,"#null-hypothesis":p.null_hypothesis,"#design-summary":p.design_summary,"#randomization-method":p.randomization_method,"#randomization-seed":p.randomization_seed,"#operational-policy":p.operational_failure_policy,"#refusal-policy":p.refusal_policy,"#missing-policy":p.missing_result_policy};Object.entries(fields).forEach(([id,v])=>$(id).value=v??"");$("#operational-consumes").checked=p.operational_failure_consumes_run===true;GROUPS.forEach(([key])=>{$(`#${key}-rows`).innerHTML="";(p[key]||[]).forEach(item=>addRow(key,item));});$("#advanced-technical-json").textContent=JSON.stringify(draft,null,2);invalidate();$("#draft-status").textContent=message;}
function restoreBrowserDraft(){let draft;try{draft=JSON.parse(localStorage.getItem("pne-study-draft")||"null");}catch(_e){return;}if(!draft)return;populateDraft(draft,"Browser-local draft restored. Validate before review.");}
async function validateDraft(){try{const body=await jsonFetch("/api/studies/validate",{method:"POST",body:JSON.stringify(collectDraft())});if(!body.valid){$("#draft-status").textContent=`Validation refused: ${body.validation_issues.map(validationIssueText).join("; ")}`;return;}validatedDraft=body.canonical_proposal;$("#review-study").disabled=false;$("#draft-status").textContent="Draft valid. Review is available. No write occurred.";}catch(e){$("#draft-status").textContent=`Validation failed: ${e.message}`;}}
function review(){if(!validatedDraft)return;$("#registration-preview").textContent=JSON.stringify(validatedDraft,null,2);$("#review-panel").hidden=false;$("#review-panel").scrollIntoView();}
async function register(){if(!validatedDraft||!confirm("Register and permanently lock this exact protocol version?"))return;try{const body=await jsonFetch("/api/studies/register",{method:"POST",body:JSON.stringify(validatedDraft)});localStorage.removeItem("pne-study-draft");$("#registration-status").textContent=`Registered version ${body.registered_protocol_version}; ${body.registered_protocol.registered_at}; ${body.registered_protocol.registration_hash}`;await openStudy(body.id);await loadStudies();}catch(e){$("#registration-status").textContent=`Registration failed: ${e.message}`;}}
function runState(run){if(run.realization)return run.realization.disposition;if(run.attempts.some(x=>x.consumes_planned_run))return "TERMINAL_OPERATIONAL_FAILURE";if(run.attempts.length)return "ATTEMPTED_OPERATIONAL_FAILURE";return "READY";}
async function openStudy(id){const study=await jsonFetch(`/api/studies/${id}`);const latest=study.protocol_versions.at(-1);const protocol=await jsonFetch(`/api/studies/${id}/protocols/${latest.version_number}`);$("#draft-panel").hidden=true;$("#review-panel").hidden=true;$("#registered-panel").hidden=false;$("#run-panel").hidden=false;$("#evaluation-panel").hidden=false;$("#exploration-panel").hidden=true;$("#closeout-panel").hidden=true;$("#registered-protocol").innerHTML=`<dl><dt>${esc(protocol.study_key)} — ${esc(protocol.title)}</dt><dd>Version ${protocol.version_number}</dd><dt>REGISTERED / IMMUTABLE</dt><dd>${esc(protocol.registered_at)}</dd><dt>Registration hash</dt><dd class="locked-value">${esc(protocol.registration_hash)}</dd><dt>Predecessor</dt><dd>${protocol.predecessor_version_id||"None"}</dd></dl><details><summary>Complete registered protocol</summary><pre>${esc(JSON.stringify(protocol,null,2))}</pre></details>`;renderRuns(protocol);$("#evaluation-completion").innerHTML='<article class="evaluation-summary"><strong>Loading Study Evaluation…</strong></article>';["#evaluation-summary","#evaluation-blocks","#evaluation-metadata","#evaluation-runs","#evaluation-analyses"].forEach(id=>$(id).innerHTML="");$("#evaluation-raw").textContent="";$("#registered-panel").scrollIntoView();try{const evaluation=await jsonFetch(`/api/studies/${id}/evaluations/${latest.version_number}`);renderEvaluation(evaluation);if(evaluation.completion.realized_runs)await loadExploration(id,latest.version_number);await loadCloseout(id,latest.version_number);}catch(e){renderEvaluationFailure(e);}}
function renderRuns(protocol){const host=$("#run-queue");host.innerHTML=[...protocol.planned_runs].sort((a,b)=>a.randomized_ordinal-b.randomized_ordinal).map(run=>`<article class="entry-card"><div class="entry-head"><strong>${run.randomized_ordinal}. ${esc(run.run_key)}</strong><span class="status">${runState(run)}</span></div><p>${esc(run.condition_key)} · ${esc(run.block_key)} · replicate ${run.replicate_number} · attempts ${run.attempts.length}</p><div class="locked-value">${esc(run.planned_prompt_text)}</div><p>${Array.from(run.planned_prompt_text).length} characters · Constraints: ${esc(run.applicable_constraint_keys.join(", "))}</p><details><summary>Execution and evidence checklist</summary><p>Submit this exact prompt once in a fresh generation. Do not regenerate, edit, delete, or substitute the result.</p><ul><li>Preserve the exact prompt and registered source system.</li><li>Capture generated playlist metadata and the complete ordered tracklist, including playlist boundaries.</li><li>Stage governed sources with their exact identity, reference, SHA-256, and observed timestamps.</li><li>Complete every required structured measurement and field-specific evidence link.</li></ul><p>Record a Maestro refusal or generation failure as a terminal result. Record a non-consuming operational failure only when Maestro produced no scientific outcome.</p></details>${!run.realization&&!run.attempts.some(x=>x.consumes_planned_run)?`<div class="study-actions"><button data-execute="${run.id}">Execute run</button><button class="secondary" data-attempt="${run.id}">Record operational failure</button><button class="secondary" data-refusal="${run.id}">Record Maestro refusal/failure</button></div>`:""}</article>`).join("");document.querySelectorAll("[data-execute]").forEach(b=>b.onclick=()=>execute(protocol,Number(b.dataset.execute)));document.querySelectorAll("[data-attempt]").forEach(b=>b.onclick=()=>attempt(protocol,Number(b.dataset.attempt)));document.querySelectorAll("[data-refusal]").forEach(b=>b.onclick=()=>failure(protocol,Number(b.dataset.refusal)));}
function displayValue(value){return value===null||value===undefined?"—":typeof value==="number"?String(Math.round(value*10000)/10000):String(value);}
function renderEvaluationFailure(error){$("#evaluation-completion").innerHTML=`<article class="evaluation-summary"><strong>Study Evaluation unavailable</strong><p>Sections 04–05 remain available. Section 06 could not be loaded: ${esc(error.message||String(error))}</p></article>`;["#evaluation-summary","#evaluation-blocks","#evaluation-metadata","#evaluation-runs","#evaluation-analyses"].forEach(id=>$(id).innerHTML="");$("#evaluation-raw").textContent="";}
function percent(value){return value===null||value===undefined?"—":`${(Number(value)*100).toFixed(1)}%`;}
function signed(value){if(value===null||value===undefined)return "—";const rounded=Math.round(Number(value)*10000)/10000;return rounded>0?`+${rounded}`:String(rounded);}
function label(value){return String(value??"").replaceAll("_"," ");}
function conditionKey(evaluation,role){return Object.entries(evaluation.summary.registered_condition_roles).find(([,registeredRole])=>registeredRole===role)?.[0];}
function primaryCondition(evaluation,key){return evaluation.summary.primary_by_condition.find(item=>item.condition_key===key);}
function exclusionsMarkup(items){return items.length?`<div class="exclusion-list"><strong>Excluded (${items.length})</strong>${items.map(item=>`<p>${esc(item.run_key||`${item.block_key||"Pair"} replicate ${item.replicate_number??"—"}`)} — ${esc(item.reason||"Registered exclusion rule applied.")}</p>`).join("")}</div>`:'<p class="quiet">Exclusions: 0</p>';}
function renderPrimary(evaluation){const primary=evaluation.summary.primary_paired_analysis;const controlKey=conditionKey(evaluation,"CONTROL");const treatmentKey=conditionKey(evaluation,"TREATMENT");const control=primaryCondition(evaluation,controlKey);const treatment=primaryCondition(evaluation,treatmentKey);const aggregate=primary?.aggregate||{};return `<article class="primary-result"><p class="result-kicker">Primary registered outcome</p><h3>${esc(evaluation.summary.primary_outcome_key)}</h3><div class="primary-metrics"><div><span>CONTROL</span><strong>${percent(control?.mean)}</strong><small>${control?.calculable_runs??0} calculable runs</small></div><div><span>NARRATIVE</span><strong>${percent(treatment?.mean)}</strong><small>${treatment?.calculable_runs??0} calculable runs</small></div><div><span>NARRATIVE − CONTROL</span><strong>${signed(aggregate.mean_difference)}</strong><small>${aggregate.pair_count??0} matched pairs</small></div></div><div class="direction-strip"><span class="negative">Negative ${aggregate.negative??0}</span><span>Zero ${aggregate.zero??0}</span><span class="positive">Positive ${aggregate.positive??0}</span></div>${exclusionsMarkup(primary?.exclusions||[])}<p class="registered-rule"><strong>Registered reporting rule:</strong> ${esc(primary?.registered_definition?.reporting_rule||"Not supplied.")}</p></article>`;}
function renderBlocks(evaluation){const classifications=new Map((evaluation.summary.replicate_consistency?.raw_results||[]).map(item=>[item.block_key,item.classification]));return evaluation.summary.primary_block_comparison.map(block=>`<article class="block-result"><div class="entry-head"><strong>${esc(block.block_key)}</strong><span class="status">${esc(label(classifications.get(block.block_key)||"NOT CALCULABLE"))}</span></div><dl><dt>Replicate 1</dt><dd>${signed(block.paired_differences[0])}</dd><dt>Replicate 2</dt><dd>${signed(block.paired_differences[1])}</dd><dt>Block mean</dt><dd>${signed(block.mean_difference)}</dd></dl></article>`).join("");}
function countOutcomes(evaluation,strategy){const grouped={};evaluation.runs.forEach(run=>{const outcome=run.outcomes.find(item=>item.strategy===strategy);if(!outcome)return;const bucket=grouped[run.condition_key]??={CALCULATED:0,MISSING:0,NOT_DERIVABLE:0,values:{}};bucket[outcome.status]=(bucket[outcome.status]||0)+1;if(outcome.status==="CALCULATED"){const key=String(outcome.value);bucket.values[key]=(bucket.values[key]||0)+1;}});return grouped;}
function renderMetadata(evaluation){const acknowledgments=countOutcomes(evaluation,"METADATA_ACKNOWLEDGMENT");const divergence=countOutcomes(evaluation,"METADATA_CONSTRUCTION_DIVERGENCE");const keys=[...new Set([...Object.keys(acknowledgments),...Object.keys(divergence)])].sort();return keys.map(key=>{const ack=acknowledgments[key]||{values:{}};const div=divergence[key]||{values:{}};return `<article class="metadata-result"><h4>${esc(key)}</h4><p><strong>Recorded acknowledgment results</strong><br>PASS ${ack.values.PASS||0} · PARTIAL ${ack.values.PARTIAL||0} · FAIL ${ack.values.FAIL||0} · UNKNOWN/MISSING ${(ack.values.UNKNOWN||0)+(ack.MISSING||0)}</p><p><strong>Derived construction divergence</strong><br>Present ${div.values[1]||0} · Not present ${div.values[0]||0} · Missing ${div.MISSING||0}</p></article>`;}).join("");}
function aggregateMarkup(aggregate){if(aggregate===null||aggregate===undefined)return '<p class="quiet">No aggregate result is derivable.</p>';if(Array.isArray(aggregate))return `<div class="analysis-data-grid">${aggregate.map(row=>`<div>${Object.entries(row).map(([key,value])=>`<span><small>${esc(label(key))}</small><strong>${esc(displayValue(value))}</strong></span>`).join("")}</div>`).join("")}</div>`;return `<dl class="analysis-aggregate">${Object.entries(aggregate).map(([key,value])=>`<dt>${esc(label(key))}</dt><dd>${esc(displayValue(value))}</dd>`).join("")}</dl>`;}
function renderAnalyses(evaluation){return evaluation.analyses.map(item=>`<article class="entry-card analysis-card ${item.status==="NOT_DERIVABLE"?"not-derivable":""}"><div class="entry-head"><strong>${esc(label(item.analysis_key))}</strong><span class="analysis-status status-${esc(item.status.toLowerCase())}">${esc(item.status)}</span></div><p><strong>Registered outcome:</strong> ${esc(item.outcome_key)}</p>${item.reason?`<p class="not-derivable-reason">${esc(item.reason)}</p>`:""}<h4>Aggregate result</h4>${aggregateMarkup(item.aggregate)}${exclusionsMarkup(item.exclusions)}<details><summary>Registered definition and underlying derived values</summary><p><strong>Population:</strong> ${esc(item.registered_definition.analysis_population)}</p><p><strong>Comparison:</strong> ${esc(item.registered_definition.comparison_definition)}</p><p><strong>Aggregation:</strong> ${esc(item.registered_definition.aggregation_rule)}</p><p><strong>Exclusion rule:</strong> ${esc(item.registered_definition.exclusion_rule)}</p><p><strong>Reporting rule:</strong> ${esc(item.registered_definition.reporting_rule)}</p>${aggregateMarkup(item.raw_results)}</details></article>`).join("");}
function renderEvaluationRuns(evaluation){return evaluation.runs.map(run=>`<details class="entry-card run-evaluation"><summary><strong>${run.randomized_ordinal}. ${esc(run.run_key)}</strong><span class="status">${esc(run.realization?.disposition||"PENDING")}</span><small>${esc(run.condition_key)} · ${esc(run.block_key)} · replicate ${run.replicate_number}</small></summary><p>Governed source: Experiment ${run.experiment_id??"—"} · GenerationFailure ${run.generation_failure_id??"—"} · PlannedRun ${run.planned_run_id}</p><div class="evaluation-constraints">${run.constraints.map(item=>`<div><strong>${esc(item.constraint_key)}</strong><span class="result-${esc((item.status||"missing").toLowerCase())}">${esc(item.status||"MISSING")}</span><p>${esc(item.constraint_text)}</p><p><strong>Recorded evidence:</strong> ${esc(item.evidence||"No recorded result evidence.")}</p><small>Constraint definition ${item.definition_id} · ConstraintResult ${item.constraint_result_id??"—"} · ${esc(item.provenance_type||"—")}</small></div>`).join("")}</div><h4>Derived read-only outcomes</h4>${run.outcomes.map(item=>`<p><strong>${esc(item.outcome_key)}</strong>: ${esc(item.status)} · ${esc(displayValue(item.value))}${item.reason?` — ${esc(item.reason)}`:""}</p>`).join("")}</details>`).join("");}
function calculatorState(item){return `${item.execution_state} / ${item.derivability_state||"—"} / ${item.calculation_state||"—"}`;}
function renderCalculatorEvaluation(evaluation){const outcomes=evaluation.runs.flatMap(run=>run.outcomes.map(item=>({run,item})));$("#evaluation-summary").innerHTML=`<article class="primary-result"><p class="result-kicker">REGISTERED CALCULATOR RESULTS</p><h3>${esc(evaluation.summary.primary_outcome_key||"Registered outcomes")}</h3><p>Values below are unchanged E2 projections. No Workbench recalculation is performed.</p>${outcomes.map(({run,item})=>`<details><summary><strong>${esc(run.run_key)} · ${esc(item.outcome_key)}</strong> — ${esc(item.status)}</summary><dl><dt>Calculator</dt><dd>${esc(item.calculator_key)}/${esc(item.calculator_version)}</dd><dt>State</dt><dd>${esc(calculatorState(item))}</dd><dt>Reason</dt><dd>${esc(item.reason_code||"—")}</dd><dt>Rate</dt><dd>${item.ratio_numerator??"—"} / ${item.ratio_denominator??"—"} = ${esc(item.value??"—")}</dd></dl><pre>${esc(JSON.stringify(item.calculator_projection,null,2))}</pre></details>`).join("")}</article>`;$("#evaluation-blocks").innerHTML="";$("#evaluation-metadata").innerHTML="";$("#evaluation-analyses").innerHTML=evaluation.analyses.map(item=>`<article class="entry-card analysis-card"><div class="entry-head"><strong>${esc(item.analysis_key)}</strong><span class="status">${esc(item.status)}</span></div><p>${esc(item.calculator_key)}/${esc(item.calculator_version)} · ${esc(calculatorState(item))}</p><p>Reason: ${esc(item.reason_code||"—")}</p><details><summary>Registered pairs, exclusions, and provenance</summary><pre>${esc(JSON.stringify(item.calculator_projection,null,2))}</pre></details></article>`).join("");$("#evaluation-runs").innerHTML=renderEvaluationRuns(evaluation);}
function renderEvaluation(evaluation){const c=evaluation.completion;$("#evaluation-completion").innerHTML=`<article class="evaluation-summary"><div class="entry-head"><strong>${c.collection_complete?"COLLECTION COMPLETE":"PROVISIONAL / INCOMPLETE"}</strong><span class="status">${c.primary_analysis_fully_calculable?"PRIMARY ANALYSIS CALCULABLE":"PRIMARY ANALYSIS INCOMPLETE"}</span></div><p>${esc(evaluation.execution_classification||"LEGACY_EXECUTION")} · ${c.realized_runs}/${c.planned_runs} realized · ${c.executable_runs} executable · ${c.refusal_count} refusals · ${c.generation_failure_count} generation failures · ${c.operational_attempt_count} operational attempts</p></article>`;if(evaluation.execution_classification==="CALCULATOR_GOVERNED_EXECUTION")renderCalculatorEvaluation(evaluation);else{$("#evaluation-summary").innerHTML=renderPrimary(evaluation);$("#evaluation-blocks").innerHTML=renderBlocks(evaluation);$("#evaluation-metadata").innerHTML=renderMetadata(evaluation);$("#evaluation-analyses").innerHTML=renderAnalyses(evaluation);$("#evaluation-runs").innerHTML=renderEvaluationRuns(evaluation);}$("#evaluation-raw").textContent=JSON.stringify(evaluation,null,2);}
function statusCounts(values){return ["PASS","PARTIAL","FAIL","UNKNOWN","MISSING"].map(status=>`${status} ${values?.[status]||0}`).join(" · ");}
function constraintResultCounts(values){return values===null||values===undefined?"Not projected":statusCounts(values);}
function contributorDetails(contributors){return `<details><summary>Contributing governed runs (${contributors.length})</summary><div class="analysis-data-grid">${contributors.map(item=>`<div><span><small>run</small><strong>${esc(item.run_key)}</strong></span><span><small>condition</small><strong>${esc(item.condition_key)}</strong></span><span><small>block / replicate</small><strong>${esc(item.block_key)} / ${item.replicate_number}</strong></span><span><small>Experiment</small><strong>${item.experiment_id??"—"}</strong></span><span><small>ConstraintResult</small><strong>${item.constraint_result_id??"—"}</strong></span><span><small>recorded status</small><strong>${esc(item.recorded_status)}</strong></span></div>`).join("")}</div></details>`;}
function renderExplorationMatrix(exploration){return exploration.constraint_matrix.map(item=>`<article class="entry-card"><div class="entry-head"><strong>${esc(item.constraint_key)}</strong><span class="status">${esc(item.constraint_type)}</span></div><p>Blocks ${esc(item.block_keys.join(", "))} · ${item.run_count} runs</p><div class="condition-counts">${Object.entries(item.conditions).map(([key,values])=>`<div><strong>${esc(key)}</strong><p>${esc(statusCounts(values))}</p><small>${values.calculable_result_count} calculable results</small></div>`).join("")}</div>${item.descriptive_binary_difference?`<p><strong>Structured binary difference:</strong> ${esc(item.descriptive_binary_difference.treatment_condition_key)} minus ${esc(item.descriptive_binary_difference.control_condition_key)} pass rate = ${signed(item.descriptive_binary_difference.treatment_minus_control_pass_rate)}</p>`:'<p class="quiet">No numeric per-constraint score is asserted for this categorical definition.</p>'}${contributorDetails(item.contributors)}</article>`).join("");}
function renderExplorationReplicates(exploration){const grouped=new Map();exploration.constraint_by_replicate.forEach(item=>{const rows=grouped.get(item.constraint_key)||[];rows.push(item);grouped.set(item.constraint_key,rows);});return [...grouped.entries()].map(([key,rows])=>`<details class="entry-card"><summary><strong>${esc(key)}</strong> — ${rows.length} recorded placements</summary><div class="replicate-grid">${rows.map(item=>`<div><strong>${esc(item.block_key)} · R${item.replicate_number} · ${esc(item.condition_key)}</strong><span class="result-${esc(item.recorded_status.toLowerCase())}">${esc(item.recorded_status)}</span><small>${esc(item.run_key)} · Experiment ${item.experiment_id??"—"} · ConstraintResult ${item.constraint_result_id??"—"}</small></div>`).join("")}</div></details>`).join("");}
function renderExactCount(exploration){const diagnostics=exploration.exact_count_diagnostics;return `<div class="condition-counts">${Object.entries(diagnostics.by_condition).map(([key,values])=>`<article><strong>${esc(key)}</strong><p>${esc(statusCounts(values))}</p></article>`).join("")}</div><div class="card-list">${diagnostics.matched_pairs.map(pair=>`<article class="entry-card"><strong>${esc(pair.block_key)} · replicate ${pair.replicate_number}</strong><div class="pair-row">${pair.conditions.map(item=>`<span>${esc(item.condition_key)}: <strong>${esc(item.recorded_status)}</strong> · generated ${item.generated_track_count??"UNKNOWN"}<small>${esc(item.run_key)} · Experiment ${item.experiment_id??"—"} · ConstraintResult ${item.constraint_result_id??"—"}</small></span>`).join("")}</div></article>`).join("")}</div>${contributorDetails(diagnostics.contributors)}<h4>Non-PASS exact-count runs</h4>${diagnostics.non_pass_runs.length?contributorDetails(diagnostics.non_pass_runs):'<p class="quiet">None.</p>'}`;}
function renderConcentration(exploration){return Object.entries(exploration.constraint_result_concentration.by_status).map(([status,rows])=>`<article class="metadata-result"><h4>${esc(status)} · ${exploration.constraint_result_concentration.totals[status]||0}</h4>${rows.filter(row=>row.count).map(row=>`<p><strong>${esc(row.constraint_key)}</strong>: ${row.count}</p>${contributorDetails(row.contributors)}`).join("")||'<p class="quiet">No recorded results.</p>'}</article>`).join("");}
function renderExploratoryMetadata(exploration){return exploration.metadata_cross_view.cells.map(cell=>`<article class="entry-card"><div class="entry-head"><strong>${esc(cell.condition_key)}</strong><span class="status">${cell.count} runs</span></div><p>Metadata <strong>${esc(cell.metadata_status)}</strong> × hard compliance <strong>${esc(cell.hard_compliance_status)}</strong></p>${contributorDetails(cell.contributors)}</article>`).join("");}
function renderStructuredExploration(exploration){const structured=exploration.structured_evaluation;$("#exploration-synopsis").innerHTML=`<article class="primary-result exploratory-summary"><p class="result-kicker">EXPLORATORY — NOT PREREGISTERED</p><p>${structured.available_population.STRUCTURED_DERIVABLE||0} structured constraints · ${structured.available_population.LEGACY_AGGREGATE_ONLY||0} aggregate-only constraints · ${structured.contributors.length} persisted subjects.</p></article>`;$("#exploration-matrix").innerHTML=structured.status_counts_by_constraint.map(item=>`<article class="entry-card"><strong>${esc(item.constraint_key)}</strong><p>${esc(statusCounts(item.status_counts))}</p></article>`).join("");$("#exploration-replicates").innerHTML=structured.status_counts_by_condition_block_replicate.map(item=>`<article class="entry-card"><strong>${esc(item.condition_key)} · ${esc(item.block_key)} · R${item.replicate_number}</strong><p>${esc(statusCounts(item.status_counts))}</p></article>`).join("");$("#exploration-exact-count").innerHTML=structured.status_counts_by_subject_kind.map(item=>`<article class="entry-card"><strong>${esc(item.subject_kind)}</strong><p>${esc(statusCounts(item.status_counts))}</p></article>`).join("");$("#exploration-concentration").innerHTML=structured.contributors.map(item=>`<details class="entry-card"><summary>${esc(item.constraint_key)} · subject ${item.subject_id} · ${esc(item.recorded_status)}</summary><p>${esc(item.run_key)} · ${esc(item.subject_kind)} · ordinal ${item.enumeration_ordinal}</p><p>ConstraintResult ${item.constraint_result_id??"—"} · SubjectResult ${item.subject_result_id??"—"} · Measurements ${esc(item.measurement_ids.join(", ")||"none")}</p><pre>${esc(JSON.stringify(item.evidence,null,2))}</pre></details>`).join("");$("#exploration-metadata").innerHTML="";$("#exploration-track-limit").innerHTML=`<article class="entry-card"><strong>${esc(exploration.track_level_analysis.status)}</strong><p>${esc(exploration.track_level_analysis.reason)}</p>${structured.non_claims.map(item=>`<p class="quiet">${esc(item)}</p>`).join("")}</article>`;}
function renderExploration(exploration){const synopsis=exploration.synopsis;$("#exploration-panel").hidden=false;if(exploration.execution_classification==="CALCULATOR_GOVERNED_EXECUTION")renderStructuredExploration(exploration);else{$("#exploration-synopsis").innerHTML=`<article class="primary-result exploratory-summary"><p class="result-kicker">${esc(synopsis.label)}</p><p>${synopsis.constraint_type_count} constraint types inspected · ${synopsis.constraint_keys_with_fail.length} with FAIL · ${synopsis.constraint_keys_with_partial.length} with PARTIAL · ${synopsis.replicate_groups_with_different_recorded_statuses} replicate groups with differing statuses.</p><p>Condition differences: ${esc(synopsis.constraint_keys_with_condition_differences.join(", ")||"none")}</p><p>Exact-count failures: ${esc(Object.entries(synopsis.exact_count_failures_by_condition).map(([key,value])=>`${key} ${value}`).join(" · "))}</p></article>`;$("#exploration-matrix").innerHTML=renderExplorationMatrix(exploration);$("#exploration-replicates").innerHTML=renderExplorationReplicates(exploration);$("#exploration-exact-count").innerHTML=renderExactCount(exploration);$("#exploration-concentration").innerHTML=renderConcentration(exploration);$("#exploration-metadata").innerHTML=renderExploratoryMetadata(exploration);$("#exploration-track-limit").innerHTML=`<article class="entry-card not-derivable"><strong>${esc(exploration.track_level_analysis.status)}</strong><p>${esc(exploration.track_level_analysis.reason)}</p></article>`;}$("#exploration-raw").textContent=JSON.stringify(exploration,null,2);}
async function loadExploration(studyId,version){try{const exploration=await jsonFetch(`/api/studies/${studyId}/explorations/${version}`);renderExploration(exploration);}catch(error){$("#exploration-panel").hidden=false;$("#exploration-synopsis").innerHTML=`<article class="evaluation-summary"><strong>Exploratory analysis unavailable</strong><p>${esc(error.message||String(error))}</p></article>`;}}
function closeoutDownloadUrl(path){return token?`${path}?session=${encodeURIComponent(token)}`:path;}
function structuredCloseoutMarkup(closeout){const item=closeout.structured_consumption;if(!item)return"";return `<article class="entry-card"><h3>Calculator and structured provenance</h3><p>${esc(item.execution_classification)} · contract ${esc(item.execution_contract_version)}</p><p>${item.structured_subject_count} subjects · ${item.subject_result_count} subject results · ${item.measurement_count} measurements · ${item.measurement_evidence_count} evidence links</p><p><strong>Outcome calculators:</strong> ${item.outcome_calculators.map(x=>`${esc(x.calculator_key)}/${esc(x.calculator_version)}`).join(" · ")}</p><p><strong>Analysis calculators:</strong> ${item.analysis_calculators.map(x=>`${esc(x.calculator_key)}/${esc(x.calculator_version)}`).join(" · ")}</p><p><strong>Unresolved registered results:</strong> ${item.unresolved_registered_results.length}</p><details><summary>Instrumentation and governed identities</summary><pre>${esc(JSON.stringify(item,null,2))}</pre></details></article>`;}
function renderCloseout(closeout,studyId,version){const registered=closeout.registered;const realized=closeout.realized;const conclusion=closeout.scientific_conclusion_boundary;const manifest=closeout.reproducibility_manifest;const follow=closeout.follow_up_readiness;const exploratory=closeout.exploratory_not_preregistered;$("#closeout-panel").hidden=false;$("#closeout-status").innerHTML=`<article class="primary-result closeout-status"><p class="result-kicker">${esc(closeout.collection_status)}</p><h3>${esc(registered.study_key)} — protocol version ${registered.protocol_version}</h3><p>Registration hash <code>${esc(registered.registration_hash)}</code></p></article>`;$("#closeout-summary").innerHTML=`<div class="closeout-grid"><article class="entry-card"><h3>REGISTERED</h3><p>${esc(registered.objective)}</p><p>${registered.conditions.length} conditions · ${registered.blocks.length} blocks · ${registered.planned_runs.length} frozen planned runs</p></article><article class="entry-card"><h3>REALIZED</h3><p>${realized.completion.realized_runs}/${realized.completion.planned_runs} realized · ${realized.completion.refusal_count} refusals · ${realized.completion.generation_failure_count} generation failures · ${realized.completion.operational_attempt_count} operational attempts</p><p>ConstraintResults: ${esc(constraintResultCounts(realized.constraint_result_status_totals))}</p></article><article class="entry-card"><h3>REGISTERED RESULTS</h3><p>Result boundary: <strong>${esc(conclusion.registered_direction)}</strong></p>${conclusion.condition_values.map(item=>`<p>${esc(item.condition_key)}: ${percent(item.mean)} across ${item.calculable_runs} runs</p>`).join("")}<p>Paired difference: ${esc(conclusion.paired_aggregate?.mean_difference??"not calculable")}</p><p>NOT_DERIVABLE: ${esc(conclusion.registered_analyses_not_derivable.join(", ")||"none")}</p></article><article class="entry-card exploratory-summary"><h3>EXPLORATORY — NOT PREREGISTERED</h3>${exploratory?`<p>${exploratory.structured_evaluation?`${exploratory.structured_evaluation.contributors.length} persisted structured subjects inspected.`:`${exploratory.synopsis.constraint_type_count} constraint types inspected.`}</p><p>${esc(exploratory.track_level_analysis.reason)}</p>`:'<p>No exploratory projection is available.</p>'}</article></div>${structuredCloseoutMarkup(closeout)}<article class="evaluation-summary"><h3>Scientific conclusion boundary</h3><p>Registered result boundary: <strong>${esc(conclusion.registered_direction)}</strong>. ${esc(conclusion.language_boundary)}</p><p>Follow-up readiness records this Study as a possible predecessor only. No follow-up Study or hypothesis was created.</p><p>Unresolved: ${esc(follow.unresolved_not_derivable_questions.join(", ")||"none")}</p></article>`;$("#closeout-exports").innerHTML=`<a class="button-link" href="${esc(closeoutDownloadUrl(`/api/studies/${studyId}/closeouts/${version}/report.json`))}" download>Download JSON research bundle</a><a class="button-link secondary" href="${esc(closeoutDownloadUrl(`/api/studies/${studyId}/closeouts/${version}/report.md`))}" download>Download Markdown report</a>`;$("#closeout-manifest").innerHTML=`<dl><dt>Study ID</dt><dd>${manifest.study_id}</dd><dt>Protocol version ID</dt><dd>${manifest.protocol_version_id}</dd><dt>Evaluation projection</dt><dd>${esc(manifest.evaluation_projection_type)}</dd><dt>Exploration projection</dt><dd>${esc(manifest.exploration_projection_type||"unavailable")}</dd><dt>SubjectResults</dt><dd>${esc((manifest.subject_result_ids||[]).join(", ")||"none")}</dd><dt>Measurements</dt><dd>${esc((manifest.measurement_ids||[]).join(", ")||"none")}</dd><dt>EvidenceSource / EvidenceLink IDs</dt><dd>${esc((manifest.structured_evidence_source_ids||[]).join(", ")||"none")} / ${esc((manifest.structured_evidence_link_ids||[]).join(", ")||"none")}</dd><dt>Repository revision</dt><dd>${esc(manifest.repository_revision||"unavailable")}</dd><dt>Report generated</dt><dd>${esc(closeout.report_generation.generated_at)} — ${esc(closeout.report_generation.timestamp_semantics)}</dd><dt>Deterministic payload SHA-256</dt><dd>${esc(closeout.deterministic_payload_sha256)}</dd></dl>`;$("#closeout-raw").textContent=JSON.stringify(closeout,null,2);}
async function loadCloseout(studyId,version){try{const closeout=await jsonFetch(`/api/studies/${studyId}/closeouts/${version}`);renderCloseout(closeout,studyId,version);}catch(error){$("#closeout-panel").hidden=false;$("#closeout-status").innerHTML=`<article class="evaluation-summary"><strong>Study closeout unavailable</strong><p>${esc(error.message||String(error))}</p></article>`;}}
function execute(protocol,id){const run=protocol.planned_runs.find(x=>x.id===id);const defs=protocol.constraint_definitions.filter(d=>run.applicable_constraint_keys.includes(d.constraint_key));sessionStorage.setItem("pne-planned-run",JSON.stringify({study_id:protocol.study_id,study_key:protocol.study_key,protocol_version:protocol.version_number,run_id:id,run_key:run.run_key,prompt:run.planned_prompt_text,source_system:run.planned_source_system,constraints:defs}));location.href=token?`/?session=${encodeURIComponent(token)}`:"/";}
async function attempt(protocol,id){const failure_code=prompt("Operational failure code");if(!failure_code)return;const notes=prompt("Describe the operator/infrastructure failure")||"";if(!notes)return;try{await jsonFetch(`/api/study-runs/${id}/operational-attempts`,{method:"POST",body:JSON.stringify({failure_code,notes})});await openStudy(protocol.study_id);}catch(e){alert(e.message);}}
async function failure(protocol,id){const run=protocol.planned_runs.find(x=>x.id===id);const refusal=confirm("OK = Maestro refusal; Cancel = other Maestro generation failure");const disposition=refusal?"MAESTRO_REFUSAL_RECORDED":"MAESTRO_FAILURE_RECORDED";const failure_type=refusal?"REFUSAL":prompt("Maestro failure type");if(!failure_type)return;const displayed_message=prompt("Exact displayed message, if available")||null;try{await jsonFetch(`/api/study-runs/${id}/failures`,{method:"POST",body:JSON.stringify({disposition,failure:{prompt:run.planned_prompt_text,source_system:run.planned_source_system,failure_type,displayed_message}})});await openStudy(protocol.study_id);}catch(e){alert(e.message);}}

const GUIDED_STEP_LABELS=["Study","Conditions","Constraint","Outcome","Analysis","Runs","Review"];
let guidedKeyEdited=false;
let guidedLanguageEdited=false;
function safeStudyKey(value){return value.normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/[^A-Z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,48)||"NEW-STUDY";}
function syncIntentDefaults(){const title=val("#guided-title");const question=val("#guided-question");if(!guidedKeyEdited)$("#guided-key").value=safeStudyKey(title);if(!guidedLanguageEdited){$("#guided-objective").value=question?`Prospectively evaluate the research question: ${question}`:"";$("#guided-primary").value=question?`The registered outcome differs between ${JSON.stringify(val("#guided-left-label"))} and ${JSON.stringify(val("#guided-right-label"))} in the direction defined by the registered analysis.`:"";$("#guided-null").value=question?`The registered outcome does not differ between ${JSON.stringify(val("#guided-left-label"))} and ${JSON.stringify(val("#guided-right-label"))}.`:"";}$("#guided-left-factor").value=`${val("#guided-left-label")}: shared base instruction plus the explicitly entered Condition A instruction.`;$("#guided-right-factor").value=`${val("#guided-right-label")}: shared base instruction plus the explicitly entered Condition B instruction.`;}
function guidedConstraintConfig(){return [...document.querySelectorAll("#guided-constraint-list [data-guided-constraint]")].map(row=>({constraintKey:row.querySelector('[data-constraint-field="key"]').value.trim(),template:row.querySelector('[data-constraint-field="template"]').value,applicability:row.querySelector('[data-constraint-field="applicability"]').value,primary:row.querySelector('[data-constraint-field="primary"]').checked,expectedCount:Number(row.querySelector('[data-constraint-field="count"]').value),expectedExplicit:row.querySelector('[data-constraint-field="explicit"]').value==="true",token:row.querySelector('[data-constraint-field="token"]').value,aggregateBehavior:row.querySelector('[data-constraint-field="aggregation"]').value,acceptedDisplayTitles:row.querySelector('[data-constraint-field="target-titles"]').value.replaceAll("\r","").split("\n").filter(value=>value!==""),displayArtist:row.querySelector('[data-constraint-field="target-artist"]').value}));}
function guidedConfig(){syncIntentDefaults();return{studyKey:val("#guided-key"),title:val("#guided-title"),researchQuestion:val("#guided-question"),objective:val("#guided-objective"),primaryHypothesis:val("#guided-primary"),nullHypothesis:val("#guided-null"),seed:val("#guided-seed"),sourceSystem:val("#guided-source-system"),operationalPolicy:val("#guided-operational"),refusalPolicy:val("#guided-refusal"),missingPolicy:val("#guided-missing"),leftKey:val("#guided-left-key"),leftLabel:val("#guided-left-label"),leftFactor:val("#guided-left-factor"),rightKey:val("#guided-right-key"),rightLabel:val("#guided-right-label"),rightFactor:val("#guided-right-factor"),basePrompt:val("#guided-base-prompt"),leftFraming:val("#guided-left-framing"),rightFraming:val("#guided-right-framing"),blockCount:Number(val("#guided-block-count")),replicates:Number(val("#guided-replicates")),constraints:guidedConstraintConfig(),outcomeKind:val("#guided-outcome-kind"),success:val("#guided-success"),unknownPolicy:val("#guided-unknown"),missingInputPolicy:val("#guided-missing-input"),refusalTreatment:val("#guided-refusal-result"),failureTreatment:val("#guided-failure-result"),direction:val("#guided-direction")};}
function renderGuidedStep(){document.querySelectorAll("[data-guided-step]").forEach(item=>item.hidden=Number(item.dataset.guidedStep)!==guidedStep);$("#guided-steps").innerHTML=GUIDED_STEP_LABELS.map((label,index)=>`<button type="button" class="${index+1===guidedStep?"active":"secondary"}" data-guided-jump="${index+1}">${index+1}. ${esc(label)}</button>`).join("");$("#guided-mobile-progress").innerHTML=`<strong>Step ${guidedStep} of 7</strong><span>${esc(GUIDED_STEP_LABELS[guidedStep-1])}</span>`;document.querySelectorAll("[data-guided-jump]").forEach(button=>button.onclick=()=>{guidedStep=Number(button.dataset.guidedJump);refreshGuided().catch(error=>$("#guided-status").textContent=error.message);});$("#guided-back").disabled=guidedStep===1;$("#guided-next").hidden=guidedStep===7;}
function promptPreviews(){const base=val("#guided-base-prompt").trim();const compose=framing=>[base,framing.trim()].filter(Boolean).join("\n\n");$("#guided-prompt-preview").innerHTML=[[val("#guided-left-label"),compose(val("#guided-left-framing"))],[val("#guided-right-label"),compose(val("#guided-right-framing"))]].map(([label,text])=>`<article class="entry-card"><strong>${esc(label||"Unnamed condition")}</strong><div class="locked-value">${esc(text||"Enter the shared instruction above.")}</div></article>`).join("");}
function directionSummary(){const left=val("#guided-left-label")||"Unnamed";const right=val("#guided-right-label")||"Unnamed";const select=$("#guided-direction");const conditionA=`Condition A — ${left}`;const conditionB=`Condition B — ${right}`;select.options[0].textContent=`${conditionB} minus ${conditionA}`;select.options[1].textContent=`${conditionA} minus ${conditionB}`;const rightMinus=select.value==="RIGHT_MINUS_LEFT";const first=rightMinus?conditionB:conditionA;const second=rightMinus?conditionA:conditionB;$("#guided-direction-help").textContent=`Choose the subtraction direction explicitly; condition names never determine it.`;$("#guided-direction-meaning").innerHTML=`<strong>${esc(first)} minus ${esc(second)}</strong><p>A positive value means ${esc(first)} had the higher registered success rate. A negative value means ${esc(first)} had the lower registered success rate.</p>`;}
function refreshConstraintRow(row){const key=row.querySelector('[data-constraint-field="template"]').value;const template=window.GuidedStudyBuilder.templates[key];row.querySelector('[data-constraint-option="count"]').hidden=key!=="exact_count";row.querySelector('[data-constraint-option="explicit"]').hidden=key!=="displayed_explicit";row.querySelector('[data-constraint-option="token"]').hidden=key!=="lexical_title";row.querySelector('[data-constraint-option="aggregation"]').hidden=key!=="displayed_explicit";row.querySelector('[data-constraint-option="target"]').hidden=key!=="target_explicit";row.querySelector("[data-constraint-technical]").innerHTML=`<strong>${esc(template.label)}</strong><p>Subject ${esc(template.subject)}${template.field?` · field ${esc(template.field)}`:""}<br>Selector ${esc(template.selector.join("/"))}<br>Evaluator ${esc(template.evaluator.join("/"))}<br>Aggregate ${esc(template.aggregate.join("/"))}${template.derivation?`<br>Derivation ${esc(template.derivation.join("/"))}`:""}<br>Authority ${esc(template.authority)} · unavailable ${key==="target_explicit"?"MAY_BE_UNAVAILABLE":"MUST_HAVE_VALUE"}</p>${key==="target_explicit"?'<p>Exact code-point matching only. Zero matches = TARGET_ABSENT; multiple matches = TARGET_AMBIGUOUS. PASS/FAIL codes observed target state, not Condition A prompt compliance.</p>':""}`;}
function addGuidedConstraint(values={}){const host=$("#guided-constraint-list");const ordinal=host.children.length+1;const row=document.createElement("article");row.className="entry-card";row.dataset.guidedConstraint="";row.innerHTML=`<div class="form-grid"><label>Rule key<input data-constraint-field="key" value="${esc(values.constraintKey||`rule-${ordinal}`)}"></label><label>Rule type<select data-constraint-field="template"><option value="exact_count">Generate an exact number of tracks</option><option value="displayed_explicit">PLAYLIST-WIDE — require or forbid displayed Explicit</option><option value="target_explicit">TARGET-SPECIFIC — observe Explicit state of one exact displayed track</option><option value="lexical_title">Require a standalone word in every displayed title</option></select></label><label>Applies to<select data-constraint-field="applicability"><option value="BOTH">Both conditions</option><option value="CONDITION_A">Condition A only</option><option value="CONDITION_B">Condition B only</option></select></label><label><input type="radio" name="guided-primary-constraint" data-constraint-field="primary"> Primary comparison rule</label><label data-constraint-option="count">How many tracks?<input type="number" min="1" data-constraint-field="count" value="${esc(values.expectedCount??10)}"></label><label data-constraint-option="explicit">Displayed Explicit designation<select data-constraint-field="explicit"><option value="false">Must be absent</option><option value="true">Must be present</option></select></label><label data-constraint-option="aggregation">Playlist result<select data-constraint-field="aggregation"><option value="MIXED_PARTIAL">Mixed passing/violating tracks = PARTIAL</option><option value="ANY_VIOLATION_FAILS">Any violating track fails the playlist</option></select></label><label data-constraint-option="token">Standalone title word<input data-constraint-field="token" value="${esc(values.token||"night")}"></label><div class="wide" data-constraint-option="target"><p class="hint">Enter every accepted exact displayed title on its own line. Nothing is added, stripped, trimmed, case-folded, or normalized.</p><label>Accepted exact displayed-title representations<textarea class="short" data-constraint-field="target-titles">${esc((values.acceptedDisplayTitles||[]).join("\n"))}</textarea></label><label>Exact displayed artist<input data-constraint-field="target-artist" value="${esc(values.displayArtist||"")}"></label><p class="warning">This is a neutral observed state: PASS = unique target Not Explicit; FAIL = unique target Explicit. FAIL is not Condition A prompt noncompliance.</p></div></div><details><summary>Technical details</summary><div data-constraint-technical></div></details><button type="button" class="ghost" data-remove-guided-constraint>Remove rule</button>`;host.append(row);row.querySelector('[data-constraint-field="template"]').value=values.template||"exact_count";row.querySelector('[data-constraint-field="applicability"]').value=values.applicability||"BOTH";row.querySelector('[data-constraint-field="explicit"]').value=String(values.expectedExplicit??false);row.querySelector('[data-constraint-field="aggregation"]').value=values.aggregateBehavior||"MIXED_PARTIAL";row.querySelector('[data-constraint-field="primary"]').checked=values.primary===true||host.children.length===1;row.querySelectorAll("input,select,textarea").forEach(input=>input.addEventListener("input",()=>refreshGuided().catch(()=>{})));row.querySelector("[data-remove-guided-constraint]").onclick=()=>{row.remove();refreshGuided().catch(()=>{});};refreshConstraintRow(row);}
function templateSummary(){document.querySelectorAll("#guided-constraint-list [data-guided-constraint]").forEach(refreshConstraintRow);}
function guidedReview(draft,validation){const p=draft.protocol;const plan=p.execution_contract.outcome_calculation_plans[0];const analysis=p.execution_contract.analysis_calculation_plans[0];const direction=analysis.parameters.find(x=>x.parameter_key==="difference_direction").text_value;const left=p.conditions.find(x=>x.condition_key===analysis.condition_bindings.find(x=>x.comparison_role==="LEFT").condition_key);const right=p.conditions.find(x=>x.condition_key===analysis.condition_bindings.find(x=>x.comparison_role==="RIGHT").condition_key);const success=plan.parameters.filter(x=>x.parameter_key==="numerator_status").map(x=>x.text_value).join(" or ");const primaryKeys=new Set(plan.constraint_bindings.map(x=>x.constraint_key));const ruleReview=p.constraint_definitions.map(item=>{const structured=item.structured_evaluation_plan;const target=structured.subject_selector.evaluator_key==="selector.exact_displayed_title_artist";const targetDetails=target?`<p><strong>Accepted exact displayed titles:</strong> ${structured.vocabulary_terms.filter(term=>term.vocabulary_key==="accepted_display_titles").map(term=>esc(term.term_definition)).join("; ")}<br><strong>Exact displayed artist:</strong> ${esc(structured.parameters.find(parameter=>parameter.parameter_key==="display_artist").text_value)}<br><strong>Match semantics:</strong> exact case-, whitespace-, punctuation-, and Unicode-sensitive strings; no normalization.<br><strong>Selection states:</strong> zero = TARGET_ABSENT; multiple = TARGET_AMBIGUOUS; unavailable observation remains UNKNOWN.</p>`:"";return `<p><strong>${primaryKeys.has(item.constraint_key)?"Primary rule":"Secondary rule"}:</strong> ${esc(item.constraint_text)}</p>${targetDetails}`;}).join("");$("#guided-review").innerHTML=`<article class="entry-card"><h3>${esc(draft.title)}</h3><p><strong>Study key:</strong> ${esc(draft.study_key)}</p><p><strong>Research question:</strong> ${esc(val("#guided-question"))}</p><p><strong>Objective:</strong> ${esc(p.objective)}</p><p><strong>Primary hypothesis:</strong> ${esc(p.primary_hypothesis)}</p><p><strong>Null hypothesis:</strong> ${esc(p.null_hypothesis)}</p></article><article class="entry-card"><h3>What will be compared</h3><p><strong>Condition A:</strong> ${esc(left.label)}</p><p><strong>Condition B:</strong> ${esc(right.label)}</p>${ruleReview}<p><strong>Success:</strong> ${esc(success)}</p><p><strong>Unknown evidence:</strong> ${esc(plan.parameters.find(x=>x.parameter_key==="unknown_policy").text_value.replaceAll("_"," ").toLowerCase())}</p><p><strong>Difference:</strong> ${direction==="RIGHT_MINUS_LEFT"?`${esc(right.label)} minus ${esc(left.label)}`:`${esc(left.label)} minus ${esc(right.label)}`}</p><p><strong>Pair policy:</strong> ${analysis.calculator_version==="2"?"Exclude and report pairs with a non-calculable member; calculate only eligible numeric pairs.":"All registered pairs are required."}</p></article><article class="entry-card"><h3>${p.planned_sample_size} planned runs in registered order</h3>${p.planned_runs.map(item=>`<p><strong>${item.randomized_ordinal}. ${esc(p.conditions.find(x=>x.condition_key===item.condition_key).label)}</strong> · ${esc(item.block_key)} · test ${item.replicate_number} · ${esc(item.applicable_constraint_keys.join(", "))}</p><div class="locked-value">${esc(item.planned_prompt_text)}</div>`).join("")}</article><article class="entry-card"><h3>Validation</h3><p>${validation.valid?"Existing backend validator: VALID":"Existing backend validator refused the draft."}</p>${validation.valid?"":`<p>${esc(validation.validation_issues.map(validationIssueText).join("; "))}</p>`}</article>`;$("#guided-technical").textContent=JSON.stringify(draft,null,2);}
async function refreshGuided(){syncIntentDefaults();renderGuidedStep();templateSummary();promptPreviews();directionSummary();if(guidedStep<6)return;const draft=await window.GuidedStudyBuilder.compile(guidedConfig());$("#guided-seed").value=draft.protocol.randomization_seed;$("#guided-run-preview").innerHTML=draft.protocol.planned_runs.map(item=>`<article class="entry-card"><strong>${item.randomized_ordinal}. ${esc(draft.protocol.conditions.find(x=>x.condition_key===item.condition_key).label)}</strong><p>${esc(item.block_key)} · test ${item.replicate_number}</p><div class="locked-value">${esc(item.planned_prompt_text)}</div></article>`).join("");if(guidedStep===7){const validation=await jsonFetch("/api/studies/validate",{method:"POST",body:JSON.stringify(draft)});guidedReview(draft,validation);generatedDraftBase=draft;$("#guided-status").textContent=validation.valid?"Generated draft passes existing validation. No write occurred.":`Validation refused: ${validation.validation_issues.map(validationIssueText).join("; ")}`;}}
function openGuided(){if(!window.GuidedStudyBuilder){alert("Guided Study Builder failed to initialize.");return;}guidedStep=1;guidedKeyEdited=false;guidedLanguageEdited=false;$("#guided-panel").hidden=false;$("#draft-panel").hidden=true;$("#review-panel").hidden=true;$("#registered-panel").hidden=true;$("#run-panel").hidden=true;$("#evaluation-panel").hidden=true;$("#exploration-panel").hidden=true;$("#closeout-panel").hidden=true;if(!$("#guided-constraint-list").children.length)addGuidedConstraint({constraintKey:"exact-count",template:"exact_count",applicability:"BOTH",primary:true});if(!val("#guided-seed"))$("#guided-seed").value=`guided-${Date.now().toString(36)}`;refreshGuided();$("#guided-panel").scrollIntoView();}
async function guidedNext(){try{if(guidedStep<7)guidedStep+=1;await refreshGuided();document.querySelector(`[data-guided-step="${guidedStep}"]`).scrollIntoView();}catch(error){$("#guided-status").textContent=`Builder could not generate draft: ${error.message}`;}}
async function guidedBack(){if(guidedStep>1)guidedStep-=1;await refreshGuided();}
async function openGuidedAdvanced(){try{const draft=generatedDraftBase||await window.GuidedStudyBuilder.compile(guidedConfig());populateDraft(draft);$("#guided-panel").hidden=true;$("#draft-panel").scrollIntoView();}catch(error){$("#guided-status").textContent=`Advanced handoff failed: ${error.message}`;}}

buildGroups();$("#guided-study").onclick=openGuided;$("#new-study").onclick=newDraft;$("#refresh-studies").onclick=loadStudies;$("#validate-study").onclick=validateDraft;$("#review-study").onclick=review;$("#back-to-draft").onclick=()=>{$("#review-panel").hidden=true;$("#draft-panel").scrollIntoView();};$("#register-study").onclick=register;$("#save-browser-draft").onclick=()=>{localStorage.setItem("pne-study-draft",JSON.stringify(collectDraft()));$("#draft-status").textContent="Draft saved only in this browser.";};$("#guided-next").onclick=guidedNext;$("#guided-back").onclick=guidedBack;$("#guided-open-advanced").onclick=openGuidedAdvanced;$("#guided-add-constraint").onclick=()=>addGuidedConstraint();$("#guided-key").addEventListener("input",()=>{guidedKeyEdited=true;});["#guided-objective","#guided-primary","#guided-null"].forEach(id=>$(id).addEventListener("input",()=>{guidedLanguageEdited=true;}));["#guided-title","#guided-question","#guided-left-label","#guided-right-label","#guided-base-prompt","#guided-left-framing","#guided-right-framing","#guided-direction"].forEach(id=>$(id).addEventListener("input",()=>{refreshGuided().catch(()=>{});}));loadStudies().catch(e=>$("#study-list").textContent=e.message);
$("#guided-study").onclick=()=>{if(requireCompatibleRuntime())openGuided();};
$("#new-study").onclick=()=>{if(requireCompatibleRuntime())newDraft();};
$("#register-study").onclick=()=>{if(requireCompatibleRuntime())register();};
verifyRuntimeIdentity();
restoreBrowserDraft();
